-- B236: native paid formation; exact grants are owned by CrewProjects.lua.

-- Preserve separately locked integer capacity at nonstandard speeds. The
-- engine still owns ordinary project cost scaling; these exact-price variants
-- correct only cases where scaling the Standard cost would introduce +1.
CREATE TEMP TABLE SPC_CrewSpeedCosts(ProjectType TEXT, BaseProject TEXT, Cost INTEGER);
SELECT p.ProjectType || '_S' || s.CostMultiplier, p.ProjectType,
       CAST((CAST(CAST(v.Capacity*s.CostMultiplier/100 AS INTEGER)*v.Ratio/100 AS INTEGER)*100+s.CostMultiplier-1)/s.CostMultiplier AS INTEGER)
FROM Projects p JOIN (
SELECT 'PROJECT_SPC_CREW_250' AS ProjectType,250 AS Capacity,150 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_250_P140' AS ProjectType,250 AS Capacity,140 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_250_P130' AS ProjectType,250 AS Capacity,130 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_250_P120' AS ProjectType,250 AS Capacity,120 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_420' AS ProjectType,420 AS Capacity,150 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_420_P140' AS ProjectType,420 AS Capacity,140 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_420_P130' AS ProjectType,420 AS Capacity,130 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_420_P120' AS ProjectType,420 AS Capacity,120 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_750' AS ProjectType,750 AS Capacity,150 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_750_P140' AS ProjectType,750 AS Capacity,140 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_750_P130' AS ProjectType,750 AS Capacity,130 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_750_P120' AS ProjectType,750 AS Capacity,120 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1000' AS ProjectType,1000 AS Capacity,150 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1000_P140' AS ProjectType,1000 AS Capacity,140 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1000_P130' AS ProjectType,1000 AS Capacity,130 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1000_P120' AS ProjectType,1000 AS Capacity,120 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1360' AS ProjectType,1360 AS Capacity,150 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1360_P140' AS ProjectType,1360 AS Capacity,140 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1360_P130' AS ProjectType,1360 AS Capacity,130 AS Ratio UNION ALL
SELECT 'PROJECT_SPC_CREW_1360_P120' AS ProjectType,1360 AS Capacity,120 AS Ratio
) v ON p.ProjectType=v.ProjectType CROSS JOIN (SELECT DISTINCT CostMultiplier FROM GameSpeeds WHERE CostMultiplier>0) s
WHERE CAST(p.Cost*s.CostMultiplier/100 AS INTEGER) <> CAST(CAST(v.Capacity*s.CostMultiplier/100 AS INTEGER)*v.Ratio/100 AS INTEGER);
SELECT s.ProjectType,p.Name,p.ShortName,p.Description,s.Cost,p.CostProgressionModel,p.PrereqDistrict,p.RequiredBuilding
FROM SPC_CrewSpeedCosts s JOIN Projects p ON p.ProjectType=s.BaseProject;
DROP TABLE SPC_CrewSpeedCosts;
